// TestConcurrentRememberSubprocesses drives N independent cavemem processes at
// one shared mem.db file — the real shape of Promise.all(facts.map(remember))
// from the JS client, which each spawn a fresh binary. On the pre-fix store the
// contending processes returned SQLITE_BUSY and dropped most writes; the
// busy_timeout(5000)+WAL DSN makes them wait so every write lands.
func TestConcurrentRememberSubprocesses(t *testing.T) {
	if testing.Short() {
		t.Skip("builds and execs the cavemem binary; skipped under -short")
	}
	tmp := t.TempDir()
	bin := helperBinaryName(tmp)
	build := exec.Command("go", "build", "-o", bin, ".")
	build.Stderr = os.Stderr
	if err := build.Run(); err != nil {
		t.Fatalf("build cavemem: %v", err)
	}

	home := filepath.Join(tmp, "home")
	const n = 24
	var wg sync.WaitGroup
	errs := make(chan error, n)
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			cmd := exec.Command(bin, "remember", fmtFact(i))
			cmd.Env = append(os.Environ(), "CAVEMAN_HOME="+home)
			var stderr bytes.Buffer
			cmd.Stderr = &stderr
			if err := cmd.Run(); err != nil {
				errs <- &subprocErr{i: i, err: err, stderr: stderr.String()}
			}
		}(i)
	}
	wg.Wait()
	close(errs)
	for err := range errs {
		t.Errorf("%v", err)
	}

	store, err := mem.Open(mem.Options{Dir: filepath.Join(home, "mem")})
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	defer store.Close()
	count, err := store.Count()
	if err != nil {
		t.Fatalf("count: %v", err)
	}
	if count != n {
		t.Fatalf("only %d of %d subprocess writes landed", count, n)
	}
}

type subprocErr struct {
	i      int
	err    error
	stderr string
}

func (e *subprocErr) Error() string {
	return "remember " + strconv.Itoa(e.i) + ": " + e.err.Error() + " (" + strings.TrimSpace(e.stderr) + ")"
}

func fmtFact(i int) string {
	return "subprocess memory number " + strconv.Itoa(i) + " about distinct topic " + strconv.Itoa(i)
}

// cavemem — thin TypeScript/JS client. It shells out to the `cavemem` Go binary
// (the single source of truth for storage, BM25 recall, and engine compression);
// it does not reimplement any of that. Resolve the binary via CAVEMEM_BIN or PATH.
import { execFile } from "node:child_process";

/** Process exit code returned when one memory exceeds the binary's byte cap. */
export const MEMORY_TOO_LARGE_EXIT_CODE = 65;

function binary() {
  return process.env.CAVEMEM_BIN || "cavemem";
}

async function call(args, input) {
  const { stdout } = await new Promise((resolve, reject) => {
    const child = execFile(binary(), args, { maxBuffer: 32 * 1024 * 1024 }, (error, out, err) => {
      if (error) reject(error);
      else resolve({ stdout: out, stderr: err });
    });
    child.stdin.on("error", (error) => {
      // Oversized input may make the binary close stdin after MaxMemoryBytes+1.
      // Its exit 65 is the contract; an EPIPE while finishing the write is not a
      // second failure and must not replace that code.
      if (error.code !== "EPIPE") reject(error);
    });
    child.stdin.end(input);
  });
  return JSON.parse(stdout);
}

/** Store a memory. Returns { id, created_at, basis }. Idempotent on identical text. */
export function remember(text) {
  return call(["remember", "--stdin"], text);
}

/** Recall memories relevant to a query. tokenBudget defaults to 2000; 0 is unlimited. */
export function recall(query, limit, tokenBudget) {
  const args = ["recall", query];
  if (limit !== undefined || tokenBudget !== undefined) args.push(String(limit ?? 0));
  if (tokenBudget !== undefined) args.push(String(tokenBudget));
  return call(args);
}

/** Replace one current memory while preserving its version history. */
export function supersede(id, text) {
  return call(["supersede", id, text]);
}

/** Return oldest-to-newest versions for a memory lineage. */
export function history(id) {
  return call(["history", id]);
}

/** Delete a memory by id. Returns { forgotten }. */
export function forget(id) {
  return call(["forget", id]);
}

{
  "name": "cavemem",
  "version": "1.0.0",
  "description": "Durable, compression-native agent memory — thin client over the cavemem binary.",
  "license": "MIT",
  "type": "module",
  "main": "index.mjs",
  "exports": {
    ".": "./index.mjs"
  },
  "files": [
    "index.mjs",
    "README.md"
  ],
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "test": "node --test --test-force-exit tests/*.test.mjs"
  }
}

import assert from "node:assert/strict";
import { chmod, mkdtemp, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";

import { MEMORY_TOO_LARGE_EXIT_CODE, forget, history, recall, remember, supersede } from "../index.mjs";

test("JS client exports the too-large process exit contract", () => {
  assert.equal(MEMORY_TOO_LARGE_EXIT_CODE, 65);
});

// The fake binary is a POSIX shebang script, which Windows cannot exec (and
// execFile refuses .cmd shims); the shipped cavemem there is a real Go .exe.
// Tests that must EXECUTE the stub skip on win32 — contract and failure-path
// tests still run everywhere.
const stubExecutable = process.platform !== "win32";

async function fakeBinary() {
  const directory = await mkdtemp(join(tmpdir(), "cavemem-js-"));
  const path = join(directory, "cavemem");
  await writeFile(path, `#!/usr/bin/env node
const { readFileSync } = require("node:fs");
const args = process.argv.slice(2);
const input = args[0] === "remember" && args[1] === "--stdin" ? readFileSync(0, "utf8") : "";
if (args.includes("__fail__") || input.includes("__fail__")) process.exit(17);
if (Buffer.byteLength(input) > 256 * 1024) process.exit(65);
if (args.includes("__invalid_json__") || input.includes("__invalid_json__")) process.stdout.write("not json");
else process.stdout.write(JSON.stringify({ args, basis: "inferred" }));
`, { mode: 0o700 });
  await chmod(path, 0o700);
  return { directory, path };
}

test("JS client forwards every command and preserves JSON response", { skip: !stubExecutable }, async (t) => {
  const previous = process.env.CAVEMEM_BIN;
  const { path } = await fakeBinary();
  process.env.CAVEMEM_BIN = path;
  t.after(() => {
    if (previous === undefined) delete process.env.CAVEMEM_BIN;
    else process.env.CAVEMEM_BIN = previous;
  });

  assert.deepEqual(await remember("raw memory"), { args: ["remember", "--stdin"], basis: "inferred" });
  assert.deepEqual(await recall("billing"), { args: ["recall", "billing"], basis: "inferred" });
  assert.deepEqual(await recall("billing", 4), { args: ["recall", "billing", "4"], basis: "inferred" });
  assert.deepEqual(await recall("billing", 4, 900), { args: ["recall", "billing", "4", "900"], basis: "inferred" });
  assert.deepEqual(await recall("billing", undefined, 0), { args: ["recall", "billing", "0", "0"], basis: "inferred" });
  assert.deepEqual(await supersede("mem_1", "replacement"), { args: ["supersede", "mem_1", "replacement"], basis: "inferred" });
  assert.deepEqual(await history("mem_1"), { args: ["history", "mem_1"], basis: "inferred" });
  assert.deepEqual(await forget("mem_1"), { args: ["forget", "mem_1"], basis: "inferred" });
});

test("JS client propagates binary and JSON failures", { skip: !stubExecutable }, async (t) => {
  const previous = process.env.CAVEMEM_BIN;
  const { path } = await fakeBinary();
  process.env.CAVEMEM_BIN = path;
  t.after(() => {
    if (previous === undefined) delete process.env.CAVEMEM_BIN;
    else process.env.CAVEMEM_BIN = previous;
  });

  await assert.rejects(remember("__fail__"), (error) => error.code === 17);
  await assert.rejects(remember("__invalid_json__"), SyntaxError);
  await assert.rejects(
    remember("x".repeat(256 * 1024 + 1)),
    (error) => error.code === MEMORY_TOO_LARGE_EXIT_CODE,
  );
});

test("explicit missing CAVEMEM_BIN fails instead of silently executing PATH binary", async (t) => {
  const previousBinary = process.env.CAVEMEM_BIN;
  const previousPath = process.env.PATH;
  const { directory } = await fakeBinary();
  process.env.CAVEMEM_BIN = join(directory, "missing-cavemem");
  process.env.PATH = `${directory}:${previousPath}`;
  t.after(() => {
    if (previousBinary === undefined) delete process.env.CAVEMEM_BIN;
    else process.env.CAVEMEM_BIN = previousBinary;
    process.env.PATH = previousPath;
  });

  await assert.rejects(remember("must not reach PATH"), (error) => error.code === "ENOENT");
});

test("unset CAVEMEM_BIN resolves cavemem from PATH", { skip: !stubExecutable }, async (t) => {
  const previousBinary = process.env.CAVEMEM_BIN;
  const previousPath = process.env.PATH;
  const { directory } = await fakeBinary();
  delete process.env.CAVEMEM_BIN;
  process.env.PATH = `${directory}:${previousPath}`;
  t.after(() => {
    if (previousBinary === undefined) delete process.env.CAVEMEM_BIN;
    else process.env.CAVEMEM_BIN = previousBinary;
    process.env.PATH = previousPath;
  });

  assert.deepEqual(await remember("path memory"), {
    args: ["remember", "--stdin"],
    basis: "inferred",
  });
});

"""cavemem — thin Python client (stdlib only).

It shells out to the ``cavemem`` Go binary (the single source of truth for
storage, BM25 recall, and engine compression); it reimplements none of that.
Resolve the binary via the ``CAVEMEM_BIN`` env var or PATH. Mirrors the TS client
in ``../js/index.mjs``.
"""
from __future__ import annotations

import json
import os
import subprocess
from typing import Any


MEMORY_TOO_LARGE_EXIT_CODE = 65


def _binary() -> str:
    return os.environ.get("CAVEMEM_BIN", "cavemem")


def _call(args: list[str], input_text: str | None = None) -> dict[str, Any]:
    kwargs: dict[str, Any] = {"capture_output": True, "text": True, "check": True}
    if input_text is not None:
        kwargs["input"] = input_text
    proc = subprocess.run([_binary(), *args], **kwargs)
    return json.loads(proc.stdout)


def remember(text: str) -> dict[str, Any]:
    """Store a memory. Returns {id, created_at, basis}. Idempotent on identical text."""
    return _call(["remember", "--stdin"], text)


def recall(
    query: str,
    limit: int | None = None,
    token_budget: int | None = None,
) -> dict[str, Any]:
    """Recall memories. token_budget defaults to 2000; explicit 0 is unlimited."""
    args = ["recall", query]
    if limit is not None or token_budget is not None:
        args.append(str(limit if limit is not None else 0))
    if token_budget is not None:
        args.append(str(token_budget))
    return _call(args)


def supersede(mem_id: str, text: str) -> dict[str, Any]:
    """Replace one current memory while preserving its version history."""
    return _call(["supersede", mem_id, text])


def history(mem_id: str) -> dict[str, Any]:
    """Return oldest-to-newest versions for a memory lineage."""
    return _call(["history", mem_id])


def forget(mem_id: str) -> dict[str, Any]:
    """Delete a memory by id. Returns {forgotten}."""
    return _call(["forget", mem_id])

package mem

import (
	"errors"
	"fmt"
	"strings"
	"testing"
)

// TestRecallRespectsTokenBudget stores several matching memories whose combined
// injected tokens exceed a small budget and asserts Recall packs them greedily
// without overshooting. Before the budget contract, Recall returned every match
// whole regardless of size.
func TestRecallRespectsTokenBudget(t *testing.T) {
	s := newStore(t)
	const memories = 12
	for i := 0; i < memories; i++ {
		// Distinct, non-repetitive text so nothing collapses via redundancy and
		// each memory carries a real, similar token cost.
		if _, err := s.Remember(fmt.Sprintf(
			"kubernetes ingress note %d covers nginx routing rule alpha%d beta%d gamma%d delta%d for the cluster",
			i, i, i, i, i)); err != nil {
			t.Fatalf("remember %d: %v", i, err)
		}
	}

	const budget = 60
	hits, err := s.Recall("kubernetes ingress nginx routing rule", RecallOptions{Limit: memories, TokenBudget: budget})
	if err != nil {
		t.Fatalf("recall: %v", err)
	}
	if len(hits) == 0 {
		t.Fatal("expected at least one hit within budget")
	}
	total := 0
	for _, h := range hits {
		total += h.TokensAdded
	}
	if total > budget {
		t.Fatalf("recall injected %d tokens, over the %d-token budget (%d hits)", total, budget, len(hits))
	}
	if len(hits) >= memories {
		t.Fatalf("budget must drop some of the %d matches, returned %d", memories, len(hits))
	}
}

func TestRecallUnlimitedSentinelReturnsEveryRankedHit(t *testing.T) {
	s := newStore(t)
	const memories = 12
	for i := 0; i < memories; i++ {
		if _, err := s.Remember(fmt.Sprintf(
